CREATE TABLE IF NOT EXISTS vehicle_market(vehicle_id BIGINT UNSIGNED PRIMARY KEY,seller_character_id BIGINT UNSIGNED NOT NULL,price BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(seller_character_id,created_at),FOREIGN KEY(vehicle_id) REFERENCES character_vehicles(id) ON DELETE CASCADE,FOREIGN KEY(seller_character_id) REFERENCES characters(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS vehicle_owner_history(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,vehicle_id BIGINT UNSIGNED NOT NULL,from_character_id BIGINT UNSIGNED NULL,to_character_id BIGINT UNSIGNED NOT NULL,price BIGINT UNSIGNED NULL,reason VARCHAR(32) NOT NULL DEFAULT 'transfer',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(vehicle_id,created_at),FOREIGN KEY(vehicle_id) REFERENCES character_vehicles(id) ON DELETE CASCADE);
